import { z } from "zod";import { db,json,requireApiUser } from "../../_shared";import { resolveFolderId } from "../folders/store";
const schema=z.object({imageUrl:z.string().url(),sourceUrl:z.string().url(),note:z.string().max(500).default(""),folderId:z.string().nullish()});
export async function POST(request:Request){const user=await requireApiUser(request);if(user instanceof Response)return user;try{const input=schema.parse(await request.json()),id=crypto.randomUUID(),now=new Date().toISOString(),folderId=await resolveFolderId(user.userId,input.folderId);await db().prepare("INSERT INTO assets (id,user_id,asset_type,external_url,source_name,source_url,license_status,risk_level,tags,metadata,folder_id,created_at) VALUES (?,?,?,?,?,?, 'unknown','yellow','[]',?,?,?)").bind(id,user.userId,"external_link",input.imageUrl,input.note||"外部图片",input.sourceUrl,JSON.stringify({note:input.note}),folderId,now).run();return json({id,folderId},{status:201})}catch(error){return json({error:error instanceof Error?error.message:"保存失败"},{status:422})}}
